#include "hardware/pio.h"
#include "constants.h"
#include "ccd_commands.h"

typedef struct smdef_s{
    PIO pio;
    uint sm;
    uint8_t offset;
} SM_def;
#define SMDEF_INVALID_VAL UINT8_MAX

typedef enum {
    CCD_Res_Full, //4800
    CCD_Res_div2, //2400
    CCD_Res_div4, //1200
    CCD_Res_div8, //600
    CCD_Res_div16 //300/preview
}CCD_Resolution_t;

int set_clock(const SM_def *smdef,int enable);
bool setup_clock(SM_def *smdef,float freq, uint gpio);
bool setup_data(SM_def *smdef,uint gpiobase);
uint32_t readData(const SM_def *smdef,uint32_t* buf,int samples);
void begin_ctrl_data_transfer(const SM_def *smdef,const uint basepin);
uint16_t read_ctrl_data_sm(const SM_def *sm_data,uint8_t cmd);

void send_ctrl_data_sm_32(const SM_def *smdef,uint32_t buf);
void send_ctrl_data_sm(const SM_def *smdef,uint8_t cmd,uint8_t data1,uint8_t data2);
void send_ctrl_data_arr(const SM_def *sm_data,const uint32_t* buf,uint32_t len);

void start_sampling(const SM_def *sm_data);
void stop_sampling(const SM_def *sm_data);

uint32_t set_resolution(const SM_def *sm_data,CCD_Resolution_t resPreset);

void set_rgb_gain_ofs(const SM_def *sm_data,uint8_t rOfs,uint8_t gOfs,uint8_t bOfs,uint8_t rGain,uint8_t gGain,uint8_t bGain);

int readFrames(const SM_def *sm_data,uint32_t* buf,int samples,uint32_t linelength);



